import re
from collections import defaultdict
from taf.rfrl.procedures.resources.python.parser.btslog_parser import filter_syslog, get_time_from_line, get_line_index
from taf.rfrl.procedures.resources.python.utilities import get_generator_items_number, append_to_file, convert_timestamp_to_datetime
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import (
    get_managed_objects_for_class, get_bts_rat_distn_from_distn, get_parameter_value_by_distn
)
from taf.rfrl.procedures.resources.python.log_verifiers.exceptions import InvalidPeriodicDelayMeasurementSession, \
    InvalidPeriodicSessionsNumber, InvalidBtsLogMessageFormat, KpiThresholdExceededError
from taf.rfrl.procedures.resources.python.parser.exceptions import NoMatchingLinesFoundError


def verify_periodic_ecipri_delay_measurements(syslog_paths, start_time, stop_time, connection, logs_path, measurements_activated=True,
                                              allow_nok_result=False):
    """
    Verify periodic eCPRI delay measurements.
    - Check if the number of created sessions in one measurement is equal to the expected number of sessions.
    - Check if all created sessions have response with result.
    - Check if the time difference from 'create sessions' in the actual and previous session is < 61 seconds.
    - Check if the result response is 'ok' if allow_nok_result is False.

    :param syslog_paths: Paths to syslog files.
    :type syslog_paths: list or str
    :param start_time: Start time for filtering syslog lines.
    :type start_time: datetime obj
    :param stop_time: Stop time for filtering syslog lines.
    :type stop_time: datetime obj
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param logs_path: Path to the test logs directory.
    :type logs_path: str
    :param measurements_activated: Indicates if the periodic delay measurements should be visible in the syslog.
    :type measurements_activated: bool
    :param allow_nok_result: Allow the periodic delay measurement result response to be different from 'ok'.
    :type allow_nok_result: bool
    :raises NoMatchingLinesFoundError: If no matching lines are found in the syslog using the provided filters.
    :raises InvalidPeriodicDelayMeasurementSession: If periodic delay measurements are found in the syslog when measurements_activated=False or
                                                    if found periodic delay measurement session(s) with errors
    :raises InvalidBtsLogMessageFormat: when incorrect format of measurement message found in btslog files
    """
    report_path = f"{logs_path}/report_verify_periodic_delay_measurements.txt"
    filters = ['Created periodic measurement:', 'created periodic measurement:', 'Periodic delay measurement result:']
    filtered_data = filter_syslog(syslog_paths, filters=filters, start_time=start_time, stop_time=stop_time)
    matched_lines = get_generator_items_number(filtered_data)

    if not matched_lines:
        if not measurements_activated:
            return
        raise NoMatchingLinesFoundError(f"No matching lines found in syslog using the provided filters: {filters}")

    if matched_lines and not measurements_activated:
        raise InvalidPeriodicDelayMeasurementSession("Periodic delay measurements are not expected to be visible in the syslog in time range: "
                                                     f"{start_time.strftime('%H:%M:%S.%f')[:-3]} - {stop_time.strftime('%H:%M:%S.%f')[:-3]}")

    periodic_measurement_session = []
    last_measurement_session = None
    expected_create_sessions = len(get_managed_objects_for_class(connection, "FHLKDLY_R"))
    last_measurement_id = None
    raise_error = False

    for line_number, line in enumerate(filtered_data, start=1):
        periodic_measurement_id = _get_periodic_measurement_id(line)

        if periodic_measurement_id == "-":
            periodic_measurement_id = last_measurement_id

        if periodic_measurement_id != last_measurement_id and last_measurement_id is not None:
            errors = _get_periodic_measurement_session_errors(periodic_measurement_session, last_measurement_session, expected_create_sessions,
                                                              allow_nok_result)
            if errors:
                raise_error = True
                append_to_file(report_path, _format_error_msg(errors, periodic_measurement_session, last_measurement_session))

            last_measurement_session, periodic_measurement_session = periodic_measurement_session, []

        periodic_measurement_session.append(line)
        last_measurement_id = periodic_measurement_id

        if line_number == matched_lines:
            errors = _get_periodic_measurement_session_errors(periodic_measurement_session, last_measurement_session, expected_create_sessions,
                                                              allow_nok_result)
            if errors and any(error[2:7] in ["ERR#3", "ERR#4"] for error in errors):
                raise_error = True
                append_to_file(report_path, _format_error_msg(errors, periodic_measurement_session, last_measurement_session))

    if raise_error:
        raise InvalidPeriodicDelayMeasurementSession(f"Invalid periodic delay measurement session(s) found. For details, check: {report_path}")


def verify_detected_equals_expected_periodic_sessions(syslog_paths, start_time, stop_time):
    """
    Verify if the number of detected periodic measurement sessions in provided time period is equal to the expected number of sessions.
    Expected number of sessions is calculated based on the first_detected_session_time and stop time.

    :param syslog_paths: paths to syslog files
    :type syslog_paths: list or str
    :param start_time: start time for filtering syslog lines
    :type start_time: datetime obj
    :param stop_time: stop time for filtering syslog lines
    :type stop_time: datetime obj
    :raises NoMatchingLinesFoundError: if no matching lines are found in the syslog using the provided filters
    :raises InvalidPeriodicSessionsNumber: if the number of detected periodic sessions is invalid within time period
    :raises InvalidBtsLogMessageFormat: when incorrect format of measurement message found in btslog files
    """
    filters = ['Created periodic measurement:', 'created periodic measurement:']
    filtered_data = filter_syslog(syslog_paths, filters=filters, start_time=start_time, stop_time=stop_time)

    if not get_generator_items_number(filtered_data):
        raise NoMatchingLinesFoundError(f"No matching lines found in syslog using the provided filters: {filters}")

    created_sessions = 0
    last_measurement_id = 0
    first_detected_session_time = None

    for line_number, line in enumerate(filtered_data, start=1):
        if line_number == 1:
            first_detected_session_time = get_time_from_line(line)
        measurement_id = _get_periodic_measurement_id(line)

        if measurement_id == "-":
            measurement_id = last_measurement_id

        if measurement_id != last_measurement_id:
            created_sessions += 1
            last_measurement_id = measurement_id

    expected_sessions = int((stop_time - first_detected_session_time).total_seconds() // 60) + 1
    if created_sessions != expected_sessions:
        raise InvalidPeriodicSessionsNumber(
            f"Invalid Number of detected periodic measurements within time period: {first_detected_session_time.strftime('%H:%M:%S.%f')[:-3]} - "
            f"{stop_time.strftime('%H:%M:%S.%f')[:-3]}\nExpected: {expected_sessions}, Detected: {created_sessions}"
        )


def verify_cell_off_on_switching_kpi(connection, cell_timestamps, switch_on_kpi=30):
    """
    Verify cell OFF/ON switching KPI based on the following criteria:
    Switch OFF KPI: t3 - t2 <= 30s + WebM param value ("shutdownWindow")
    Switch ON KPI: t6 - t5 <= 30s
    *t2 - Time when BTS decide that the cell needs to be switch OFF for energy saving.
    *t3 - Time when the cell is disabled and enters energy saving state.
    *t5 - Time when the BTS decide that the cell needs to be switch ON.
    *t6 - Time when the cell is enabled and leaves energy saving state.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_timestamps: Dictionary with cell timestamps.
                            e.g. {'MRBTS-40615/NRBTS-406/NRCELL-0': {'t1': '2025-10-08 19:11:09', 't2': '2025-10-07 19:12:02.978',
                                                                     't3': '2025-10-07 19:13:03.494', 't4': '2025-10-08 19:14:09',
                                                                     't5': '2025-10-07 19:14:03.494', 't6': '2025-10-07 19:16:03.494'}}
    :type cell_timestamps: dict
    :param switch_on_kpi: Switch ON KPI limit in seconds. Default is 30s.
    :type switch_on_kpi: int
    """
    timestamp_format = '%Y-%m-%d %H:%M:%S.%f'
    switch_off_kpi_per_rat = {}
    cells_exceeded_kpi_limit = defaultdict(list)

    for cell_distn, timestamps in cell_timestamps.items():
        timestamps = {key: convert_timestamp_to_datetime(value, timestamp_format) for key, value in timestamps.items() if key not in ['t1', 't4']}
        bts_rat_distn = get_bts_rat_distn_from_distn(cell_distn)
        if bts_rat_distn not in switch_off_kpi_per_rat:
            shutdown_window = get_parameter_value_by_distn(connection=connection, dist_name=bts_rat_distn, parameter='shutdownWindow')
            switch_off_kpi_per_rat[bts_rat_distn] = 30 + int(shutdown_window)

        switch_off_kpi = switch_off_kpi_per_rat[bts_rat_distn]
        delta_t3_t2 = (timestamps['t3'] - timestamps['t2']).total_seconds()
        delta_t6_t5 = (timestamps['t6'] - timestamps['t5']).total_seconds()

        if delta_t3_t2 > switch_off_kpi:
            cells_exceeded_kpi_limit[cell_distn].append(
                f"switch OFF kpi exceeded: t2 - {timestamps['t2']}, t3 - {timestamps['t3']}, "
                f"delta_t3_t2 - {delta_t3_t2}s, kpi_limit - {switch_off_kpi}s"
            )

        if delta_t6_t5 > switch_on_kpi:
            cells_exceeded_kpi_limit[cell_distn].append(
                f"switch ON kpi exceeded: t6 - {timestamps['t6']}, t5 - {timestamps['t5']}, "
                f"delta_t6_t5 - {delta_t6_t5}s, kpi_limit - {switch_on_kpi}s"
            )

    if cells_exceeded_kpi_limit:
        error_messages = '\n'.join(["{}: {}".format(cell, ', '.join(msgs)) for cell, msgs in cells_exceeded_kpi_limit.items()])
        raise KpiThresholdExceededError(f"Cells exceeded KPI limits:\n{error_messages}")


def verify_cell_tx_off_on_switching_kpi(cell_timestamps, switch_on_off_kpi=30):
    """
    Verify cell TX OFF/ON switching KPI based on the following criteria:
    Switch OFF KPI: t3 - t2 <= 30s
    Switch ON KPI: t6 - t5 <= 30s
    *t2 - Time when the BTS SW decides that the cell TXes needs to be switched OFF for energy saving.
    *t3 - Time when the cell TXes are disabled and enters energy saving state (reducedEnergySaving).
    *t5 - Time when the BTS SW decides that the cell TXes needs to be switched ON and leave energy saving state.
    *t6 - Time when the cell TXes are enabled and leaves energy saving state.

    :param cell_timestamps: Dictionary with cell timestamps.
                            e.g. {'MRBTS-40615/NRBTS-406/NRCELL-0': {'t1': '2025-10-08 19:11:09', 't2': '2025-10-07 19:12:02.978',
                                                                     't3': '2025-10-07 19:13:03.494', 't4': '2025-10-08 19:14:09',
                                                                     't5': '2025-10-07 19:14:03.494', 't6': '2025-10-07 19:16:03.494'}}
    :type cell_timestamps: dict
    :param switch_on_off_kpi: Switch ON/OFF KPI limit in seconds. Default is 30s.
    :type switch_on_off_kpi: int
    :raises KpiThresholdExceededError: if any cell exceeded KPI limits
    """
    timestamp_format = '%Y-%m-%d %H:%M:%S.%f'
    cells_exceeded_kpi_limit = defaultdict(list)

    for cell_distn, timestamps in cell_timestamps.items():
        timestamps = {key: convert_timestamp_to_datetime(value, timestamp_format) for key, value in timestamps.items() if key not in ['t1', 't4']}

        switch_off = (timestamps['t3'] - timestamps['t2']).total_seconds()
        switch_on = (timestamps['t6'] - timestamps['t5']).total_seconds()

        if switch_off > switch_on_off_kpi:
            cells_exceeded_kpi_limit[cell_distn].append(
                f"TX switch OFF kpi exceeded: t2 - {timestamps['t2']}, t3 - {timestamps['t3']}, "
                f"delta_t3_t2 - {switch_off}s, kpi_limit - {switch_on_off_kpi}s"
            )

        if switch_on > switch_on_off_kpi:
            cells_exceeded_kpi_limit[cell_distn].append(
                f"TX switch ON kpi exceeded: t6 - {timestamps['t6']}, t5 - {timestamps['t5']}, "
                f"delta_t6_t5 - {switch_on}s, kpi_limit - {switch_on_off_kpi}s"
            )

    if cells_exceeded_kpi_limit:
        error_messages = '\n'.join(["{}: {}".format(cell, ', '.join(msgs)) for cell, msgs in cells_exceeded_kpi_limit.items()])
        raise KpiThresholdExceededError(f"Cells exceeded KPI limits:\n{error_messages}")


def verify_deep_sleep_responsiveness_kpi(rmod_timestamps, deep_sleep_kpi=60):
    """
    Verifies RMOD deep sleep responsiveness KPI based on the following criteria:
    1. KPI: t3 - t1 <= deep_sleep_kpi
       *t1 - time when the energy save period starts
       *t3 - time when the RMOD enters deep sleep mode
    2. KPI: t7 - t4 <= deep_sleep_kpi
       *t4 - time when the energy save period ends
       *t7 - time when all the cells mapped to the RMOD are enabled and leave energy saving state

    :param rmod_timestamps: Dictionary with rmod timestamps.
                            e.g. {'MRBTS-40615/NRBTS-406/RMOD-1: {'t1': '2025-10-08 19:11:09', 't2': '2025-10-07 19:12:02.978',
                                                                  't3': '2025-10-07 19:13:03.494', 't4': '2025-10-08 19:14:09',
                                                                  't5': '2025-10-07 19:14:03.494', 't6': '2025-10-07 19:16:03.494'}}
    :type rmod_timestamps: dict
    :param deep_sleep_kpi: Deep Sleep Responsiveness KPI limit in seconds. It can be provided as a single integer value,
                           or as a dictionary with specific RMOD KPI limits. Default is 60s for all RMODs.
                           e.g. {'MRBTS-40615/NRBTS-406/RMOD-1': 60, 'MRBTS-40615/NRBTS-406/RMOD-2': 45}
    :type deep_sleep_kpi: dict | int
    :raises KpiThresholdExceededError: if any rmod exceeded KPI limits
    """
    timestamp_format = '%Y-%m-%d %H:%M:%S.%f'
    rmod_exceeded_kpi_limit = defaultdict(list)

    for rmod_distn, timestamps in rmod_timestamps.items():
        timestamps = {key: convert_timestamp_to_datetime(value, timestamp_format) for key, value in timestamps.items()
                      if key in ['t1', 't3', 't4', 't7']}

        delta_t3_t1 = (timestamps['t3'] - timestamps['t1']).total_seconds()
        delta_t7_t4 = (timestamps['t7'] - timestamps['t4']).total_seconds()

        if delta_t3_t1 > deep_sleep_kpi:
            rmod_exceeded_kpi_limit[rmod_distn].append(
                f"- t1 - {timestamps['t1']}, t3 - {timestamps['t3']}, delta_t3_t1 - {delta_t3_t1}s, kpi_limit - {deep_sleep_kpi}s"
            )

        if delta_t7_t4 > deep_sleep_kpi:
            rmod_exceeded_kpi_limit[rmod_distn].append(
                f"- t4 - {timestamps['t4']}, t7 - {timestamps['t7']}, delta_t7_t4 - {delta_t7_t4}s, kpi_limit - {deep_sleep_kpi}s"
            )

    if rmod_exceeded_kpi_limit:
        error_messages = '\n'.join(["{}:\n{}\n".format(rmod, '\n'.join(msgs)) for rmod, msgs in rmod_exceeded_kpi_limit.items()])
        raise KpiThresholdExceededError(f"Deep Sleep Responsiveness kpi exceeded:\n{error_messages}")


def _get_periodic_measurement_id(line):
    """
    Get measurement ID from syslog line. Line should be filtered using the following case-insensitive filters:
    'created periodic measurement:' or 'periodic delay measurement result:'.
    In case of measurement with 'periodic delay measurement result:' phrase and missing `lastMeasurementId` parameter,
    measurement ID is returned as '-' character.

    :param line: filtered syslog line
    :type line: str
    :return: measurement ID from syslog line e.g. '1' or '-' in case of missing lastMeasurementId parameter.
    :rtype: str

    :raises InvalidBtsLogMessageFormat: when incorrect format of measurement message
    """
    if re.search(r"(?i)created periodic measurement:", line):
        pattern = r'(measurementId|measId)\s=\s([0-9]+)'
        result = re.search(pattern, line)
        if result is not None:
            return re.search(pattern, line).group(2)

    elif re.search(r"(?i)periodic delay measurement result", line):
        pattern = r'lastMeasurementId\s([0-9]+)'
        result = re.search(pattern, line)
        return result.group(1) if result is not None else "-"

    raise InvalidBtsLogMessageFormat(f"Invalid measurement message format: {line}")


def _get_periodic_data_from_line(line, log_type):
    """
    Gets data from periodic syslog line. Line should be filtered using the following filters:
    'Created periodic measurement:', 'created periodic measurement:' or 'Periodic delay measurement result:'.

    :param line: filtered syslog line
    :type line: str
    :param log_type: type of line to parse ('create' or 'result')
    :type log_type: str
    :return: parsed filtered syslog line e.g. {'session_id_1': {'line_index': 1, 'local_time': datetime, 'result': 'ok'}}
    :rtype: dict
    """
    session_id = 'session_id_' + re.search(r'sessionId\s=?\s?([0-9]+)', line).group(1)
    periodic_data = {session_id: {'line_index': get_line_index(line),
                                  'local_time': get_time_from_line(line)}}
    if log_type == 'result':
        found_result = re.search(r'\s(ok|nok),', line)
        periodic_data[session_id]['result'] = found_result.group(1) if found_result is not None else None

    return periodic_data


def _get_periodic_measurement_session_errors(measurement_session, last_measurement_session, expected_create_sessions, allow_nok_result=False):
    """
    Get periodic delay measurement session errors based on the following criteria:
    - check if the number of created sessions in one measurement is equal to the expected number of sessions
    - check if all created sessions have response with result
    - check if the time from 'create sessions' in the actual and previous session is < 61 seconds.
    - check if the result response is 'ok' if allow_nok_result is False.

    :param measurement_session: Syslog lines from one periodic measurement session
    :type measurement_session: list
    :param last_measurement_session: Syslog lines from last periodic measurement session
    :type last_measurement_session: list
    :param expected_create_sessions: expected number of 'created periodic measurement' sessions in one measurement
    :type expected_create_sessions: int or str
    :param allow_nok_result: Allow the periodic delay measurement result response to be different from 'ok'.
    :type allow_nok_result: bool
    :return: list of errors
    :rtype: list of str
    """
    errors = []

    measurement_session = _parse_periodic_measurement_session(measurement_session)
    last_measurement_session = _parse_periodic_measurement_session(last_measurement_session) if last_measurement_session else {}

    create_sessions = measurement_session['create']
    result_responses = measurement_session['result']
    last_create_sessions = last_measurement_session.get('create', {})

    if not len(create_sessions.keys()) == expected_create_sessions:
        errors.append(f"- ERR#1 expected: '{expected_create_sessions}' sessions with 'created periodic measurement' in one measurement "
                      f"but found '{len(create_sessions)}'.")

    for create_session_id, create_session_data in create_sessions.items():
        last_create_session = last_create_sessions.get(create_session_id, None)
        create_time_diff = (create_session_data['local_time'] - last_create_session['local_time']).total_seconds() if last_create_session else 0

        if create_session_id not in result_responses:
            errors.append(f"- ERR#2 [{create_session_data['line_index']}] created periodic {create_session_id} has no result response.")

        if last_measurement_session and create_time_diff > 61:
            errors.append(f"- ERR#3 [{create_session_data['line_index']}] created periodic measurement: {create_session_id}, "
                          f"time difference between the actual and previous session is greater than 61s. Difference: {create_time_diff}s.")

        if result_responses.get(create_session_id, None):
            if result_responses[create_session_id]['result'] != 'ok' and not allow_nok_result:
                errors.append(f"- ERR#4 [{create_session_data['line_index']}] created periodic measurement sessionId: {create_session_id} has failed."
                              f" Result response line: [{result_responses[create_session_id]['line_index']}] - "
                              f"'{result_responses[create_session_id]['result']}'.")

    return errors


def _parse_periodic_measurement_session(periodic_measurement_session):
    """
    Parse periodic measurement session data.

    :param periodic_measurement_session: Syslog lines from one periodic measurement session
    :type periodic_measurement_session: list
    :return: parsed periodic measurement session data e.g. {'create': {'session_id_1': {'line_index': 1, 'local_time': datetime}},
                                                            'result': {'session_id_1': {'line_index': 1, 'local_time': datetime, 'result': 'ok'}}
    :rtype: dict
    """
    periodic_session = defaultdict(dict)
    for line in periodic_measurement_session:
        log_type = 'create' if re.search(r"(?i)created periodic measurement:", line) else 'result'
        periodic_session[log_type].update(_get_periodic_data_from_line(line, log_type))
    return periodic_session


def _format_error_msg(errors, periodic_measurement_session, last_measurement_session):
    """
    Format error message.

    :param errors: list of errors
    :type errors: list
    :param periodic_measurement_session: periodic measurement session data
    :type periodic_measurement_session: list
    :param last_measurement_session: last periodic measurement session data
    :type last_measurement_session: list
    :return: formatted error message
    :rtype: str
    """
    periodic_measurement_session = '  '.join(periodic_measurement_session)
    last_measurement_session = '  '.join(last_measurement_session) if last_measurement_session else []
    return (f"Periodic delay measurement session with errors:\n"
            f"[validated session]:\n  {periodic_measurement_session}\n"
            f"[last session]:\n  {last_measurement_session}\n"
            f"[errors]:\n  " + '\n  '.join(errors) + '\n\n')
